-- Textures and fonts the addon ships, plus the lookups used by the bars and the config window.
-- Textures are generated by tools/make_media.py, fonts are Open Sans (see Fonts/OFL.txt).
BReST.Media = {}
local M = BReST.Media

local PATH = "Interface\\AddOns\\BrzEnhancedSwingTimer\\"
M.path = PATH

M.white = PATH .. "Textures\\white.tga"
M.spark = PATH .. "Textures\\spark.tga"
M.check = PATH .. "Textures\\check.tga"
M.arrow = PATH .. "Textures\\arrow.tga"
M.close = PATH .. "Textures\\close.tga"
M.gradH = PATH .. "Textures\\grad_h.tga"
M.gradV = PATH .. "Textures\\grad_v.tga"
M.hue = PATH .. "Textures\\hue.tga"
M.ring = PATH .. "Textures\\ring.tga"

M.fontUI = PATH .. "Fonts\\OpenSans-Regular.ttf"
M.fontUIBold = PATH .. "Fonts\\OpenSans-SemiBold.ttf"
M.fontFallback = "Fonts\\FRIZQT__.TTF"

M.fallbackIcon = "Interface\\Icons\\INV_Misc_QuestionMark"

-- name is what is saved in the profile, label is what the menus show
M.textures = {
    { name = "Flat", label = "Flat", path = M.white },
    { name = "Gradient", label = "Gradient", path = PATH .. "Textures\\bar_gradient.tga" },
    { name = "Glossy", label = "Glossy", path = PATH .. "Textures\\bar_glossy.tga" },
    { name = "Smooth", label = "Smooth", path = PATH .. "Textures\\bar_smooth.tga" },
    { name = "Stripes", label = "Stripes", path = PATH .. "Textures\\bar_stripes.tga" },
}

M.fonts = {
    { name = "Open Sans", label = "Open Sans", path = PATH .. "Fonts\\OpenSans-Regular.ttf" },
    { name = "Open Sans Semibold", label = "Open Sans Semibold", path = PATH .. "Fonts\\OpenSans-SemiBold.ttf" },
    { name = "Open Sans Bold", label = "Open Sans Bold", path = PATH .. "Fonts\\OpenSans-Bold.ttf" },
    { name = "Open Sans Condensed", label = "Open Sans Condensed", path = PATH .. "Fonts\\OpenSans-CondensedBold.ttf" },
    { name = "Friz Quadrata", label = "Friz Quadrata", path = "Fonts\\FRIZQT__.TTF" },
    { name = "Arial Narrow", label = "Arial Narrow", path = "Fonts\\ARIALN.TTF" },
    { name = "Skurri", label = "Skurri", path = "Fonts\\skurri.ttf" },
    { name = "Morpheus", label = "Morpheus", path = "Fonts\\MORPHEUS.ttf" },
}

local function find(list, name)
    for i = 1, table.getn(list) do
        if list[i].name == name then return list[i] end
    end
end

-- Entries for a dropdown, plus a "Custom" one that takes a path typed by the user
local function options(list)
    local opts = {}
    for i = 1, table.getn(list) do
        table.insert(opts, { value = list[i].name, text = list[i].label })
    end
    table.insert(opts, { value = "Custom", text = "Custom path..." })
    return opts
end

function M.TextureOptions() return options(M.textures) end
function M.FontOptions() return options(M.fonts) end

function M.TexturePath(name, custom)
    if name == "Custom" then
        if type(custom) == "string" and custom ~= "" then return custom end
        return M.white
    end
    local t = find(M.textures, name)
    return t and t.path or M.white
end

function M.FontPath(name, custom)
    if name == "Custom" then
        if type(custom) == "string" and custom ~= "" then return custom end
        return M.fontUI
    end
    local f = find(M.fonts, name)
    return f and f.path or M.fontUI
end

-- A FontString must have a font before it gets any text, and a bad path leaves it without one
function M.SetFont(fs, path, size, flags)
    fs:SetFont(path, size, flags or "")
    if fs:GetFont() == nil then
        fs:SetFont(M.fontFallback, size, flags or "")
    end
end
